INSERT INTO sentences (id, language_id, text, reading_kana, level_id, source, published) VALUES
INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-nikanshite-1', 'sent-ex-nikanshite-1', 'en', 'We are investigating the accident.', 'authored'),
  ('st-ex-nikanshite-2', 'sent-ex-nikanshite-2', 'en', 'I would like to hear your view on that problem.', 'authored'),
  ('st-ex-nikanshite-3', 'sent-ex-nikanshite-3', 'en', 'I am giving a presentation on the environment.', 'authored'),
  ('st-ex-nikanshite-4', 'sent-ex-nikanshite-4', 'en', 'I will explain about the cost.', 'authored'),
  ('st-ex-nisotte-1', 'sent-ex-nisotte-1', 'en', 'I walked along the river.', 'authored'),
  ('st-ex-nisotte-2', 'sent-ex-nisotte-2', 'en', 'Trees stand along the road.', 'authored'),
  ('st-ex-nisotte-3', 'sent-ex-nisotte-3', 'en', 'We will proceed in line with the plan.', 'authored'),
  ('st-ex-nisotte-4', 'sent-ex-nisotte-4', 'en', 'Please act in accordance with the rules.', 'authored'),
  ('st-ex-nihanshite-1', 'sent-ex-nihanshite-1', 'en', 'Contrary to expectations, he won.', 'authored'),
  ('st-ex-nihanshite-2', 'sent-ex-nihanshite-2', 'en', 'Against our hopes, the result was poor.', 'authored'),
  ('st-ex-nihanshite-3', 'sent-ex-nihanshite-3', 'en', 'He acted against the rules.', 'authored'),
  ('st-ex-nihanshite-4', 'sent-ex-nihanshite-4', 'en', 'Against his parents'' wishes, he went abroad.', 'authored'),
  ('st-ex-nikagirazu-1', 'sent-ex-nikagirazu-1', 'en', 'Adults can enjoy it too, not just children.', 'authored'),
  ('st-ex-nikagirazu-2', 'sent-ex-nikagirazu-2', 'en', 'It is popular abroad as well as in Japan.', 'authored'),
  ('st-ex-nikagirazu-3', 'sent-ex-nikagirazu-3', 'en', 'We are busy in summer as well as in winter.', 'authored'),
  ('st-ex-nikagirazu-4', 'sent-ex-nikagirazu-4', 'en', 'Teachers can take part too, not only students.', 'authored'),
  ('st-ex-nikagiri-1', 'sent-ex-nikagiri-1', 'en', 'It is free for students only.', 'authored'),
  ('st-ex-nikagiri-2', 'sent-ex-nikagiri-2', 'en', 'Today only, it is cheaper.', 'authored'),
  ('st-ex-nikagiri-3', 'sent-ex-nikagiri-3', 'en', 'Only members may use it.', 'authored'),
  ('st-ex-nikagiri-4', 'sent-ex-nikagiri-4', 'en', 'Only those who booked may go in.', 'authored'),
  ('st-ex-hanmen-1', 'sent-ex-hanmen-1', 'en', 'It is convenient, but on the other side of that the price is high.', 'authored'),
  ('st-ex-hanmen-2', 'sent-ex-hanmen-2', 'en', 'The work is busy, but interesting with it.', 'authored'),
  ('st-ex-hanmen-3', 'sent-ex-hanmen-3', 'en', 'That shop is cheap, but the food is not good.', 'authored'),
  ('st-ex-hanmen-4', 'sent-ex-hanmen-4', 'en', 'The city is convenient, and for that very reason crowded.', 'authored'),
  ('st-ex-ippoude-1', 'sent-ex-ippoude-1', 'en', 'While the economy grows, the environment gets worse.', 'authored'),
  ('st-ex-ippoude-2', 'sent-ex-ippoude-2', 'en', 'While the population rises, the number of children falls.', 'authored'),
  ('st-ex-ippoude-3', 'sent-ex-ippoude-3', 'en', 'As things get more convenient, there are also things we lose.', 'authored'),
  ('st-ex-ippoude-4', 'sent-ex-ippoude-4', 'en', 'He is strict, and at the same time there is a kind side to him.', 'authored'),
  ('st-ex-mononara-1', 'sent-ex-mononara-1', 'en', 'If I could go home, I would.', 'authored'),
  ('st-ex-mononara-2', 'sent-ex-mononara-2', 'en', 'If I could go, I would want to.', 'authored'),
  ('st-ex-mononara-3', 'sent-ex-mononara-3', 'en', 'If it were possible, I would like to try.', 'authored'),
  ('st-ex-mononara-4', 'sent-ex-mononara-4', 'en', 'If I could see her, I would want to.', 'authored'),
  ('st-ex-youmononara-1', 'sent-ex-youmononara-1', 'en', 'If I were to fail, it would be a disaster.', 'authored'),
  ('st-ex-youmononara-2', 'sent-ex-youmononara-2', 'en', 'If I so much as turn up late, I get told off.', 'authored'),
  ('st-ex-youmononara-3', 'sent-ex-youmononara-3', 'en', 'If he were to forget, he would be furious.', 'authored'),
  ('st-ex-youmononara-4', 'sent-ex-youmononara-4', 'en', 'If I said that, I would be laughed at.', 'authored'),
  ('st-ex-toittemo-1', 'sent-ex-toittemo-1', 'en', 'I can speak English, but only a little.', 'authored'),
  ('st-ex-toittemo-2', 'sent-ex-toittemo-2', 'en', 'I say house, but it is a small flat.', 'authored'),
  ('st-ex-toittemo-3', 'sent-ex-toittemo-3', 'en', 'I say trip, but I only went to the next town.', 'authored'),
  ('st-ex-toittemo-4', 'sent-ex-toittemo-4', 'en', 'I say busy, but I have time to rest.', 'authored')
